/**
 * FoodShareAI - Risk Assessment Model
 * Stores behavioral anomaly assessments generated by Isolation Forest and heuristic monitors.
 * Flags outlier operational patterns for human administrative governance without automatic punishment.
 */
const mongoose = require('mongoose');

const riskAssessmentSchema = new mongoose.Schema(
  {
    entityType: {
      type: String,
      required: [true, 'Entity type is required'],
      enum: {
        values: ['DONATION', 'USER', 'CLAIM', 'DELIVERY'],
        message: '{VALUE} is not a supported risk entity type',
      },
      default: 'DONATION',
      index: true,
    },
    entityId: {
      type: mongoose.Schema.Types.ObjectId,
      required: [true, 'Target entity ID is required'],
      index: true,
    },
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      required: [true, 'Associated user ID is required'],
      index: true,
    },
    isAnomaly: {
      type: Boolean,
      default: false,
    },
    anomalyScore: {
      type: Number,
      default: 0.0,
      min: 0.0,
      max: 1.0,
    },
    riskLevel: {
      type: String,
      enum: {
        values: ['LOW', 'MEDIUM', 'HIGH'],
        message: '{VALUE} is not a valid risk level',
      },
      default: 'LOW',
      index: true,
    },
    reasons: {
      type: [String],
      default: [],
    },
    features: {
      type: mongoose.Schema.Types.Mixed,
      default: {},
    },
    modelVersion: {
      type: String,
      default: 'isolation_forest_v1',
    },
    status: {
      type: String,
      enum: {
        values: ['PENDING', 'REVIEWED', 'DISMISSED', 'CONFIRMED'],
        message: '{VALUE} is not a valid review status',
      },
      default: 'PENDING',
      index: true,
    },
    reviewedBy: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'User',
      default: null,
    },
    reviewedAt: {
      type: Date,
      default: null,
    },
    reviewNotes: {
      type: String,
      trim: true,
      default: '',
      maxlength: [1000, 'Review notes cannot exceed 1000 characters'],
    },
  },
  {
    timestamps: true,
  }
);

// Performance & governance query indexes
riskAssessmentSchema.index({ entityType: 1, entityId: 1 });
riskAssessmentSchema.index({ userId: 1, createdAt: -1 });
riskAssessmentSchema.index({ riskLevel: 1, status: 1 });
riskAssessmentSchema.index({ status: 1, createdAt: -1 });

const RiskAssessment = mongoose.model('RiskAssessment', riskAssessmentSchema);

module.exports = RiskAssessment;
